mapper.select:
SELECT S.CREATE_DATE AS createDate, S.TEMP_C AS tempC, S.HUMIDITY AS humidity, S.SOIL_MOISTURE_VALUE AS soilMoistureValue, S.LDR_VALUE AS ldrValue FROM SENSOR_DATA S JOIN DEVICE D ON S.DEVICE_ID = D.DEVICE_ID WHERE D.CROP_ID = #{cropId} AND D.IS_ACTIVE = 1
AND S.CREATE_DATE >= #{startDate}
ORDER BY S.CREATE_DATE DESC LIMIT #{limit}
